     4→using System;
     5→using System.Diagnostics;
     6→using System.Threading;
     7→using System.Threading.Tasks;
     8→using Nethermind.Api;
     9→using Nethermind.Blockchain;
    10→using Nethermind.Consensus;
    11→using Nethermind.Consensus.Producers;
    12→using Nethermind.Core.Specs;
    13→using Nethermind.JsonRpc;
    14→using Nethermind.Merge.Plugin.Data;
    15→using Nethermind.Merge.Plugin.GC;
    16→using Nethermind.Merge.Plugin.Handlers;
    17→
    18→namespace Nethermind.Merge.Plugin;
    19→
    20→public partial class EngineRpcModule : IEngineRpcModule
    21→{
    22→    private readonly IAsyncHandler<byte[], ExecutionPayload?> _getPayloadHandlerV1;
    23→    private readonly IAsyncHandler<ExecutionPayload, PayloadStatusV1> _newPayloadV1Handler;
    24→    private readonly IForkchoiceUpdatedHandler _forkchoiceUpdatedV1Handler;
    25→    private readonly IHandler<TransitionConfigurationV1, TransitionConfigurationV1> _transitionConfigurationHandler;
    26→    private readonly IEngineRequestsTracker _engineRequestsTracker;
    27→    private readonly SemaphoreSlim _locker = new(1, 1);
    28→    private readonly TimeSpan _timeout = TimeSpan.FromSeconds(8);
    29→    private readonly GCKeeper _gcKeeper;
    30→
    31→    public ResultWrapper<TransitionConfigurationV1> engine_exchangeTransitionConfigurationV1(
    32→        TransitionConfigurationV1 beaconTransitionConfiguration) => _transitionConfigurationHandler.Handle(beaconTransitionConfiguration);
    33→
    34→    public Task<ResultWrapper<ForkchoiceUpdatedV1Result>> engine_forkchoiceUpdatedV1(ForkchoiceStateV1 forkchoiceState, PayloadAttributes? payloadAttributes = null)
    35→        => ForkchoiceUpdated(forkchoiceState, payloadAttributes, EngineApiVersions.Paris);
    36→
    37→    public Task<ResultWrapper<ExecutionPayload?>> engine_getPayloadV1(byte[] payloadId) =>
    38→        _getPayloadHandlerV1.HandleAsync(payloadId);
    39→
    40→    public Task<ResultWrapper<PayloadStatusV1>> engine_newPayloadV1(ExecutionPayload executionPayload)
    41→        => NewPayload(executionPayload, EngineApiVersions.Paris);
    42→
    43→    protected async Task<ResultWrapper<ForkchoiceUpdatedV1Result>> ForkchoiceUpdated(ForkchoiceStateV1 forkchoiceState, PayloadAttributes? payloadAttributes, int version)
    44→    {
    45→        _engineRequestsTracker.OnForkchoiceUpdatedCalled();
    46→        if (await _locker.WaitAsync(_timeout))
    47→        {
    48→            long startTime = Stopwatch.GetTimestamp();
    49→            try
    50→            {
    51→                return await _forkchoiceUpdatedV1Handler.Handle(forkchoiceState, payloadAttributes, version);
    52→            }
    53→            finally
    54→            {
    55→                Metrics.ForkchoiceUpdedExecutionTime = (long)Stopwatch.GetElapsedTime(startTime).TotalMilliseconds;
    56→                _locker.Release();
    57→            }
    58→        }
    59→        else
    60→        {
    61→            if (_logger.IsWarn) _logger.Warn($"engine_forkchoiceUpdated{version} timed out");
    62→            return ResultWrapper<ForkchoiceUpdatedV1Result>.Fail("Timed out", ErrorCodes.Timeout);
    63→        }
    64→    }
    65→
    66→    protected async Task<ResultWrapper<PayloadStatusV1>> NewPayload(IExecutionPayloadParams executionPayloadParams, int version)
    67→    {
    68→        _engineRequestsTracker.OnNewPayloadCalled();
    69→        ExecutionPayload executionPayload = executionPayloadParams.ExecutionPayload;
    70→        executionPayload.ExecutionRequests = executionPayloadParams.ExecutionRequests;
    71→
    72→        if (!executionPayload.ValidateFork(_specProvider))
    73→        {
    74→            if (_logger.IsWarn) _logger.Warn($"The payload is not supported by the current fork");
    75→            return ResultWrapper<PayloadStatusV1>.Fail("unsupported fork", version < EngineApiVersions.Shanghai ? ErrorCodes.InvalidParams : MergeErrorCodes.UnsupportedFork);
    76→        }
    77→
    78→        IReleaseSpec releaseSpec = _specProvider.GetSpec(executionPayload.BlockNumber, executionPayload.Timestamp);
    79→        ValidationResult validationResult = executionPayloadParams.ValidateParams(releaseSpec, version, out string? error);
    80→        if (validationResult != ValidationResult.Success)
    81→        {
    82→            if (_logger.IsWarn) _logger.Warn(error);
    83→            return validationResult == ValidationResult.Fail
    84→                ? ResultWrapper<PayloadStatusV1>.Fail(error!, ErrorCodes.InvalidParams)
    85→                : ResultWrapper<PayloadStatusV1>.Success(PayloadStatusV1.Invalid(null, error));
    86→        }
    87→
    88→        if (await _locker.WaitAsync(_timeout))
    89→        {
    90→            long startTime = Stopwatch.GetTimestamp();
    91→            try
    92→            {
    93→                using IDisposable region = _gcKeeper.TryStartNoGCRegion();
    94→                return await _newPayloadV1Handler.HandleAsync(executionPayload);
    95→            }
    96→            catch (BlockchainException exception)
    97→            {
    98→                if (_logger.IsDebug) _logger.Error($"DEBUG/ERROR engine_newPayloadV{version} failed: {exception}");
    99→                return ResultWrapper<PayloadStatusV1>.Fail(exception.Message, ErrorCodes.UnknownBlockError);
   100→            }
   101→            catch (Exception exception)
   102→            {
   103→                if (_logger.IsError) _logger.Error($"engine_newPayloadV{version} failed: {exception}");
   104→                return ResultWrapper<PayloadStatusV1>.Fail(exception.Message);
   105→            }
   106→            finally
   107→            {
   108→                Metrics.NewPayloadExecutionTime = (long)Stopwatch.GetElapsedTime(startTime).TotalMilliseconds;
   109→                _locker.Release();
   110→            }
   111→        }
   112→        else
   113→        {
   114→            if (_logger.IsWarn) _logger.Warn($"engine_newPayloadV{version} timed out");
   115→            return ResultWrapper<PayloadStatusV1>.Fail("Timed out", ErrorCodes.Timeout);
   116→        }
   117→    }
   118→}
