    33→/// <summary>
    34→/// Provides an execution payload handler as defined in Engine API
    35→/// <a href="https://github.com/ethereum/execution-apis/blob/main/src/engine/shanghai.md#engine_newpayloadv2">
    36→/// Shanghai</a> specification.
    37→/// </summary>
    38→public sealed class NewPayloadHandler : IAsyncHandler<ExecutionPayload, PayloadStatusV1>, IDisposable
    39→{
    40→    private readonly IPayloadPreparationService _payloadPreparationService;
    41→    private readonly IBlockValidator _blockValidator;
    42→    private readonly IBlockTree _blockTree;
    43→    private readonly IPoSSwitcher _poSSwitcher;
    44→    private readonly IBeaconSyncStrategy _beaconSyncStrategy;
    45→    private readonly IBeaconPivot _beaconPivot;
    46→    private readonly IBlockCacheService _blockCacheService;
    47→    private readonly IBlockProcessingQueue _processingQueue;
    48→    private readonly IMergeSyncController _mergeSyncController;
